package com.campus.personnel.api;

import com.campus.testsupport.PostgresApplicationTest;
import java.time.Instant;import java.util.*;import com.campus.identity.domain.*;import com.campus.identity.infrastructure.security.TokenService;import com.campus.organization.application.OrganizationUnitManagementService;import com.campus.organization.domain.*;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.*;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.http.MediaType;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.test.context.ActiveProfiles;import org.springframework.test.web.servlet.MockMvc;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test") @PostgresApplicationTest class AdminFacultyStaffControllerIntegrationTest{@Autowired MockMvc mvc;@Autowired UserAccountRepository users;@Autowired RoleRepository roles;@Autowired PasswordEncoder passwords;@Autowired TokenService tokens;@Autowired OrganizationUnitManagementService organizations;@Test void restrictsAndManagesFacultyStaff()throws Exception{String user=tokens.accessToken(account("person-user@campus.example",RoleCode.USER));mvc.perform(get("/api/v1/admin/faculty-staff")).andExpect(status().isUnauthorized());mvc.perform(get("/api/v1/admin/faculty-staff").header("Authorization","Bearer "+user)).andExpect(status().isForbidden());String admin=tokens.accessToken(account("person-admin@campus.example",RoleCode.ADMIN));UUID unit=organizations.create("BUS","Business",OrganizationUnitType.FACULTY,OrganizationUnitStatus.ACTIVE).id();String body=mvc.perform(post("/api/v1/admin/faculty-staff").header("Authorization","Bearer "+admin).contentType(MediaType.APPLICATION_JSON).content("{\"personnelNumber\":\"P001\",\"fullName\":\"Faculty One\",\"personnelType\":\"FACULTY\",\"organizationUnitId\":\""+unit+"\"}")).andExpect(status().isCreated()).andExpect(jsonPath("$.personnelType").value("FACULTY")).andReturn().getResponse().getContentAsString();String id=body.replaceFirst(".*\\\"id\\\":\\\"([^\\\"]+).*","$1");mvc.perform(put("/api/v1/admin/faculty-staff/"+id).header("Authorization","Bearer "+admin).contentType(MediaType.APPLICATION_JSON).content("{\"personnelNumber\":\"P001\",\"fullName\":\"Staff One\",\"personnelType\":\"STAFF\",\"organizationUnitId\":\""+unit+"\",\"status\":\"INACTIVE\",\"expectedVersion\":0}")).andExpect(status().isOk()).andExpect(jsonPath("$.rowVersion").value(1));}@Test void rejectsDuplicateAndUnavailableUnit()throws Exception{String admin=tokens.accessToken(account("person-errors@campus.example",RoleCode.ADMIN));UUID active=organizations.create("ART","Arts",OrganizationUnitType.FACULTY,OrganizationUnitStatus.ACTIVE).id();UUID inactive=organizations.create("OFF","Office",OrganizationUnitType.ADMINISTRATIVE,OrganizationUnitStatus.INACTIVE).id();String req="{\"personnelNumber\":\"P002\",\"fullName\":\"Person Two\",\"personnelType\":\"STAFF\",\"organizationUnitId\":\""+active+"\"}";mvc.perform(post("/api/v1/admin/faculty-staff").header("Authorization","Bearer "+admin).contentType(MediaType.APPLICATION_JSON).content(req)).andExpect(status().isCreated());mvc.perform(post("/api/v1/admin/faculty-staff").header("Authorization","Bearer "+admin).contentType(MediaType.APPLICATION_JSON).content(req)).andExpect(status().isConflict()).andExpect(jsonPath("$.code").value("PERSONNEL_NUMBER_ALREADY_EXISTS"));mvc.perform(post("/api/v1/admin/faculty-staff").header("Authorization","Bearer "+admin).contentType(MediaType.APPLICATION_JSON).content("{\"personnelNumber\":\"P003\",\"fullName\":\"Person Three\",\"personnelType\":\"STAFF\",\"organizationUnitId\":\""+inactive+"\"}")).andExpect(status().isConflict()).andExpect(jsonPath("$.code").value("ORGANIZATION_UNIT_UNAVAILABLE"));}private UserAccount account(String e,RoleCode r){return users.save(UserAccount.create(UUID.randomUUID(),e,e,passwords.encode("valid-password"),AccountStatus.ACTIVE,Set.of(roles.findByCode(r).orElseThrow()),Instant.now()));}}
